# Reference objectives (#375): one file per problem, `ext/MetaData/references/<problem>.toml`,
# written by `tools/references/update.jl` from the results of the convergence tests, one
# table per scheme. Read into the field `:reference_objective` of the metadata, a field
# generated by tools (`Metadata.METADATA_SCHEMA.generated`), filled below once the metadata
# is loaded.
const REFERENCES_PATH = joinpath(Metadata.METADATA_PATH, "references")
# The fields of a table, and how each is read: a type, or a function of the TOML value.
const REFERENCE_FIELDS = (
    value=Float64,
    grid_size=Int,
    parameters=String,
    source=Symbol,
    agreement=Bool,
    spread=Float64,
    run=String,
    # the known solutions (#378): the objectives of the distinct solutions reached, best first
    solutions=tables -> Float64[t["objective"] for t in tables],
)

"""
Relative gap below which two objectives are the same solution (#378): above the accuracy of
the solvers at the tolerance of the tests (about 1e-6 at `tol = 1e-8`), below the gap between
the known local solutions (1.6e-4 on `mountain_car`). Used to group the solutions reached,
to say whether the configurations agree, and to say which solution a solve reached.
"""
const SAME_SOLUTION = 1e-5

"""Relative gap of `a` to `b` (absolute when `b` is zero)."""
_relative_gap(a, b) = abs(a - b) / (iszero(b) ? 1 : abs(b))
# a new directory changes `METADATA_PATH`, already a dependency
isdir(REFERENCES_PATH) && Base.include_dependency(REFERENCES_PATH)

function _references(
    problem::Symbol, file::AbstractString=joinpath(REFERENCES_PATH, "$(problem).toml")
)
    isfile(file) || return nothing
    Base.include_dependency(file)
    entries = Pair{Symbol,NamedTuple}[]
    for (scheme, table) in TOML.parsefile(file)
        table isa AbstractDict ||
            error("Reference objective $(scheme) of $(problem): not a table")
        values = map(keys(REFERENCE_FIELDS)) do key
            haskey(table, string(key)) || error(
                "Missing field $(key) in the reference objective $(scheme) of $(problem)",
            )
            return REFERENCE_FIELDS[key](table[string(key)])
        end
        push!(entries, Symbol(scheme) => NamedTuple{keys(REFERENCE_FIELDS)}(values))
    end
    return NamedTuple(entries)
end

for problem in Metadata.PROBLEM_NAMES
    references = _references(problem)
    isnothing(references) ||
        (Metadata.METADATA_STORAGE[problem][:reference_objective] = references)
end

"""
$(TYPEDSIGNATURES)

Return the reference objective of `problem` discretized on `grid_size` steps with `scheme`,
or `nothing` when the problem has none for this discretization.

The reference objectives are computed from the convergence tests of every modeling and
configuration, by `tools/references/update.jl`: the best objective among the solves that
converged. They are stored in `problem_metadata(problem)[:reference_objective]`, with how
they were obtained.

# Example

```julia-repl
julia> OptimalControlProblems.reference_objective(:beam)
8.889...
```
"""
function reference_objective(
    problem::Symbol;
    grid_size::Int=Metadata.grid_size_data(problem),
    scheme::Symbol=:trapeze,
)
    references = get(Metadata.problem_metadata(problem), :reference_objective, nothing)
    isnothing(references) && return nothing
    entry = get(references, scheme, nothing)
    (isnothing(entry) || entry.grid_size != grid_size) && return nothing
    return entry.value
end

"""
$(TYPEDSIGNATURES)

Return the analytic solution of the continuous `problem` for `parameters` (merged with the
default ones), or `nothing` when none is known for them: a named tuple with `state` and
`control`, functions of the time, the `objective`, and its `source`.

It is the solution of the continuous problem: the objective of a discretized problem differs
from it by the discretization error, which the reference objective includes.

# Example

```julia-repl
julia> OptimalControlProblems.reference_solution_data(:beam).objective
8.88888888888889
```
"""
function reference_solution_data(
    problem::Symbol, parameters::Union{Nothing,NamedTuple}=nothing
)
    solution = get(Metadata.problem_metadata(problem), :reference_solution, nothing)
    isnothing(solution) && return nothing
    return solution(Metadata.parameters_data(problem, parameters))
end

"""
$(TYPEDSIGNATURES)

Which known solution of `problem` the objective `objective` is, for the discretization on
`grid_size` steps with `scheme` (#378): `:best` (the reference objective), `:local` (another
known solution), `:new` (none of them), or `nothing` when the problem has no reference for
this discretization. Two objectives are the same solution within a relative
`OptimalControlProblems.SAME_SOLUTION`.
"""
function solution_kind(
    problem::Symbol,
    objective::Real;
    grid_size::Int=Metadata.grid_size_data(problem),
    scheme::Symbol=:trapeze,
)
    reference = reference_objective(problem; grid_size, scheme)
    isnothing(reference) && return nothing
    _relative_gap(objective, reference) <= SAME_SOLUTION && return :best
    solutions = Metadata.problem_metadata(problem)[:reference_objective][scheme].solutions
    any(s -> _relative_gap(objective, s) <= SAME_SOLUTION, solutions) && return :local
    return :new
end
